Register IPN URL.code:
// Register an Instant Payment Notification (IPN) URL.
// Paths are relative to the Pesapal API base (e.g. .../pesapalv3/api/).
post('URLSetup/RegisterIPN', {
  // Where Pesapal sends payment notifications (e.g. an OpenFn webhook).
  url: 'https://app.openfn.org/i/your-webhook-id',
  // GET or POST.
  ipn_notification_type: 'POST',
});

Submit Payment Order.code:
// Submit an order for payment (e.g. a clinic fee or school levy).
post('Transactions/SubmitOrderRequest', {
  // Your unique reference for this order.
  id: $.data.invoiceNumber,
  currency: 'KES',
  amount: $.data.amount,
  description: 'Community health insurance premium',
  // Where the payer is sent after paying.
  callback_url: 'https://example.org/payment-complete',
  // The ipn_id returned by RegisterIPN.
  notification_id: $.data.ipnId,
  billing_address: {
    email_address: 'member@example.org',
    phone_number: $.data.phone,
    country_code: 'KE',
    first_name: 'Wanjiru',
    last_name: 'Kamau',
  },
});

Request Refund.code:
// Request a refund for a confirmed payment.
post('Transactions/RefundRequest', {
  // Confirmation code from the completed transaction.
  confirmation_code: $.data.confirmationCode,
  amount: $.data.refundAmount,
  // User requesting the refund.
  username: 'finance.officer',
  remarks: 'Duplicate payment',
});

Cancel Pending Order.code:
// Cancel a pending order.
post('Transactions/CancelOrder', {
  // Order tracking ID returned by SubmitOrderRequest.
  order_tracking_id: $.data.orderTrackingId,
});

Get Transaction Status.code:
// Check the status of a transaction.
get('Transactions/GetTransactionStatus', {
  query: {
    // Order tracking ID from SubmitOrderRequest or the IPN.
    orderTrackingId: $.data.OrderTrackingId,
  },
});
